def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to ``maxsize`` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    import functools
    from collections import OrderedDict

    def decorating_function(user_function):
        cache = OrderedDict()  # key -> (result, count)

        @functools.wraps(user_function)
        def wrapper(*args, **kwargs):
            key = args
            if kwargs:
                # Use a frozenset of sorted keyword items to make kwargs hashable
                key += tuple(sorted(kwargs.items()))
            if typed:
                key += tuple(type(v) for v in args)
                if kwargs:
                    key += tuple(type(v) for _, v in sorted(kwargs.items()))
            if key in cache:
                result, count = cache.pop(key)
                cache[key] = (result, count + 1)
                return result
            # Compute new result
            result = user_function(*args, **kwargs)
            cache[key] = (result, 1)
            if len(cache) > maxsize:
                # Find key(s) with minimum count
                min_count = min(c for _, c in cache.values())
                # Among those, find first inserted (OrderedDict preserves order)
                for k, (_, c) in cache.items():
                    if c == min_count:
                        cache.pop(k)
                        break

