def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    import datetime
    if not isinstance(dt, (datetime.date, datetime.datetime)):
        raise TypeError(f"Expected datetime.date or datetime.datetime, got {type(dt)!r}")
    if isinstance(dt, datetime.datetime):
        if dt.tzinfo is None:
            return dt.strftime('%Y-%m-%dT%H:%M:%S')
        else:
            # Convert to UTC and use Z suffix
            return dt.astimezone(datetime.timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
    else:  # date only
        return dt.strftime('%Y-%m-%d')

