def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files."""
        # Retrieve the include directive if present
        includes = parser_dict.get('include')
        if not includes:
            return

        # Normalise to a list
        if isinstance(includes, str):
            includes = [includes]

        # Resolve each included group recursively and merge its dict into parser_dict
        for inc_name in includes:
            # Locate the group definition (assumed accessible via self._get_group)
            group_dict = self._get_group(inc_name)
            if group_dict is None:
                raise KeyError(f"Included group '{inc_name}' not found.")

