def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Ensure the object defines a mapping of argument names to allowed choices
    if not hasattr(self, 'choices') or not isinstance(self.choices, dict):
        # No choice restrictions defined, nothing to validate
        return

    for name, value in args.items():
        if name in self.choices:
            allowed = self.choices[name]
            # Support iterable values for multi-select arguments
            if isinstance(value, (list, tuple, set)):
                for v in value:
                    if v not in allowed:
                        raise ValueError(
                            f"Invalid value '{v}' for argument '{name}'. "
                            f"Allowed choices: {allowed}"
                        )
            else:
                if value not in allowed:
                    raise ValueError(
                        f"Invalid value '{value}' for argument '{name}'. "
                        f"Allowed choices: {allowed}"
                    )

