def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise ValueError(f"root does not match beginning of path: {path!r} does not start with {root!r}")
    new_path = path[len(root):]
    # strip leading separators
    if new_path and new_path[0] in ('/', '\\'):
        new_path = new_path[1:]
    return new_path

